def print_substrings(s, k):
    if k <= 0:
        return

    previous_index = 0
    for i in range(len(s)):
        if k == 0:
            continue
        curr_index = i + 1
        while curr_index <= len(s) - k + 1:
            print(s[previous_index:curr_index], end=" ")
            previous_index = curr_index

s = input().strip()
k = int(input())
print_substrings(s, k)
